ive_identity_key":"nlscale:20261102:ol:OL267619W"}'::jsonb as exact union all select 'editions:7' as ref,(select to_jsonb(t) from public.editions t where t.id=987228002)='{"id":987228002,"title":"Asterix op Corsica","isbn_10":null,"isbn_13":"9789032004767","work_id":987128002,"cover_id":13137507,"language":"dut","publisher":"Dargaud Benelux/Oberon","publish_date":null,"open_library_edition_id":"OL12802739M"}'::jsonb as exact union all select 'catalog_work_descriptions:8' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987128002 and t.language='nl')='{"text":"Asterix en Obelix reizen naar Corsica, waar een plaatselijk stamhoofd hun hulp nodig heeft tegen de Romeinse machthebbers. Het eiland kent eigen gewoonten, sterke familiebanden en langdurige vetes. Terwijl verzetsstrijders zich in het dichte struikgewas schuilhouden, proberen de Romeinen hun gezag te behouden. De twee Galliërs moeten hun weg vinden tussen die tegenstellingen. Goscinny schreef het verhaal en Uderzo tekende het avontuur, waarin de strijd tegen de bezetter samengaat met botsingen tussen verschillende manieren van leven.","work_id":987128002,"evidence":[{"note":"ExactDutch48p paperback9789032004767 is singleAsterixEnCorse#20, not4-albumomnibus9789032030469. PrimaryscriptRenéGoscinny/artAlbertUderzo confirmed independently; do not create combinedperson or treatartist as different Workauthor. PublishercurrentEnglish2014ebook is contentproof only; Dutch1980/1981printing dates remain distinct from original1973. No automatic tasteeligibility.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p045617724","https://data.bibliotheken.nl/id/nbt/p842428593"],"reference":"new-work-dossier-readings-029.json#98","checked_at":"2026-11-02T22:48:16.876Z"},{"type":"original_substantive_source_review","review":"content-amendment-010.json","sources":["https://www.hachette.co.uk/titles/ren%C3%A9-goscinny-2/asterix-asterix-in-corsica/9781444013